  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 Honest Selling and Communication$j$, $j${"readings": [{"title": "Proverbs 16 (King James Version)", "url": "/portal/bible/Proverbs/16"}], "body": "Selling is helping a person decide to buy something that truly meets a need. It is not tricking or pressuring. Proverbs 16:21 says, The wise in heart shall be called prudent: and the sweetness of the lips increaseth learning. Kind and clear speech makes a good seller.\n\nA simple selling process has five steps. First, greet the customer with respect and a smile. Second, ask questions and listen to learn the need. Third, explain how your product or service meets that need, naming benefits rather than only features. A feature is a fact about the product, such as a waterproof cover. A benefit is what the feature does for the customer, such as keeping notes dry in the rain. Fourth, answer objections honestly. An objection is a concern, such as price or timing. Fifth, ask for the sale politely and thank the customer whether or not they buy.\n\nHonest selling means never lying about quality, never hiding flaws, never pressuring a person who is unsure and never taking advantage of the young, the elderly or the confused. Written communication matters too. Emails, texts and messages should be polite, correct and professional. Answer within a reasonable time, confirm details in writing and keep a record of agreements. For students, route business messages through an account that a parent or guardian can see, and do not share private details.\n\nPractice builds confidence. Role play with a friend, record yourself and improve. Colossians 4:6 says, Let your speech be alway with grace, seasoned with salt.\n\nYour task: (1) Define feature, benefit and objection. (2) Write a thirty second honest sales pitch for your idea. (3) List three practices that make selling honest.\n\nFlorida standards: Florida Entrepreneurship course standards (course 8812100).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida Entrepreneurship course standards (course 8812100)", "script": "Welcome back. Listen, Proverbs 16:21 says, The wise in heart shall be called prudent: and the sweetness of the lips increaseth learning. Kind and clear speech makes a good seller.\n\nNow watch this. Selling is helping a person buy something that truly meets a need. The steps are greet, ask and listen, explain benefits, answer objections honestly, and ask politely for the sale. Always thank the customer.\n\nA feature is a fact about the product. A benefit is what it does for the customer. An objection is a concern such as price or timing.\n\nHonest selling never lies, never hides flaws and never pressures. Written messages should be polite, correct and professional. Students should use accounts a parent or guardian can see.\n\nPractice builds confidence. Colossians 4:6 says, Let your speech be alway with grace, seasoned with salt.\n\nYour task is to define three terms, write a pitch and list three honest practices. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 Honest Selling and Communication$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 Customer Service That Honors God$j$, $j${"readings": [{"title": "Matthew 20 (King James Version)", "url": "/portal/bible/Matthew/20"}], "body": "Customer service is how you treat people before, during and after a sale. Matthew 20:26 says, whosoever will be great among you, let him be your minister. Great businesses are built by servants. Jesus washed feet, and a business leader can serve with the same humility.\n\nExcellent service includes being on time, being friendly, listening, keeping promises, solving problems quickly and following up. A satisfied customer returns and tells others. An unhappy customer tells even more people. The cost of keeping a customer is usually much lower than the cost of finding a new one.\n\nComplaints are opportunities. When a customer is upset, use these steps: listen without interrupting, apologize sincerely for the problem, ask what would make it right, offer a fair solution, act quickly and follow up. Proverbs 15:1 says, A soft answer turneth away wrath: but grievous words stir up anger. Stay calm and never argue or insult. If the customer is abusive or you feel unsafe, politely end the conversation and involve an adult.\n\nReturn and refund policies should be written, fair and clear. Know what is promised, such as a warranty, which is a promise to repair or replace a faulty product for a period of time. Protect customer privacy: keep names, phone numbers and payment details safe, share them with no one who does not need them and never post them online.\n\nAsk for feedback with a short survey or a simple question, thank people for kind words and learn from criticism.\n\nYour task: (1) Define customer service, warranty and refund policy. (2) Write the steps for handling a complaint. (3) Role play a complaint and describe how you would respond.\n\nFlorida standards: Florida Entrepreneurship course standards (course 8812100).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida Entrepreneurship course standards (course 8812100)", "script": "Welcome back. Listen, Matthew 20:26 says, whosoever will be great among you, let him be your minister. Great businesses are built by servants.\n\nNow watch this. Customer service is how you treat people before, during and after a sale. Be on time, friendly, honest and quick to solve problems. A satisfied customer returns and tells others.\n\nComplaints are opportunities. Listen without interrupting, apologize sincerely, ask what would make it right, offer a fair solution and follow up. Proverbs 15:1 says, A soft answer turneth away wrath. If a customer is abusive or you feel unsafe, politely end the conversation and involve an adult.\n\nReturn and refund policies should be written, fair and clear. A warranty is a promise to repair or replace a faulty product. Protect customer privacy at all times.\n\nYour task is to define three terms, list complaint steps and role play a response. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 Customer Service That Honors God$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Operations, Suppliers and Quality$j$, $j${"readings": [{"title": "Proverbs 24 (King James Version)", "url": "/portal/bible/Proverbs/24"}], "body": "Operations are the daily activities that produce and deliver your product or service. Proverbs 24:3 and 4 says, Through wisdom is an house builded; and by understanding it is established: And by knowledge shall the chambers be filled with all precious and pleasant riches. Good operations are built on wisdom and understanding.\n\nA supplier is a person or company that provides the materials you need. Choose suppliers who are reliable, fair and honest. Compare prices, quality and delivery time. Keep a list of at least two suppliers for important items so that a problem with one does not stop your business. Pay suppliers on time. Inventory is the stock of goods you hold. Too little inventory loses sales. Too much ties up cash and may spoil or go out of style. Track what you have, what sells and when to reorder.\n\nQuality means that your product or service does what you promised, every time. Set a standard, check your work before delivery and fix mistakes quickly. Consistent quality builds a good name. Safety is part of quality. Follow safety rules for food, tools, chemicals and equipment, and never let a young worker handle dangerous machines. Food businesses must meet health rules; check with the state and local authorities and adult supervisors before selling any food.\n\nTime management is also an operation. Use a calendar, plan each week, set priorities and rest. Ephesians 5:16 says, Redeeming the time, because the days are evil. A simple checklist for each job prevents forgotten steps.\n\nYour task: (1) Define supplier, inventory and quality. (2) Create a weekly operations checklist for your idea. (3) Name two safety rules for your business.\n\nFlorida standards: Florida Entrepreneurship course standards (course 8812100).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida Entrepreneurship course standards (course 8812100)", "script": "Welcome back. Listen, Proverbs 24:3 and 4 says, Through wisdom is an house builded; and by understanding it is established. Good operations are built on wisdom.\n\nNow watch this. Operations are the daily activities that produce and deliver your product or service. A supplier provides the materials you need. Choose reliable, fair suppliers, compare price, quality and delivery, and pay on time. Keep two suppliers for important items.\n\nInventory is the stock of goods you hold. Too little loses sales. Too much ties up cash. Track what sells and when to reorder.\n\nQuality means doing what you promised every time. Check your work and fix mistakes quickly. Safety is part of quality. Food businesses must meet health rules, so check with authorities and adults before selling food.\n\nEphesians 5:16 says, Redeeming the time. Use a calendar and a checklist.\n\nYour task is to define three terms, make a checklist and name two safety rules. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Operations, Suppliers and Quality$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Technology, Online Business and Safety$j$, $j${"readings": [{"title": "Proverbs 14 (King James Version)", "url": "/portal/bible/Proverbs/14"}], "body": "Technology lets small businesses reach more people at lower cost. A website, an online store, a payment app, a scheduling tool and a spreadsheet can help you work well. Proverbs 14:15 says, The simple believeth every word: but the prudent man looketh well to his going. Be prudent online.\n\nOnline business has special rules. Sellers must describe products honestly, deliver on time and respect refund policies. Many places require disclosure of fees, taxes and shipping. If you collect information from customers, protect it and tell customers how you use it. Federal law has special rules for collecting information from children under thirteen. Do not copy photos, text, music or software without permission, because copyright protects creators. Use original work, licensed work or work in the public domain.\n\nPayments should go through trusted services. For a student business, payment accounts must be set up with a parent or guardian, because minors generally cannot open them alone. Never share passwords, account numbers or private details in lessons, messages or posts. Use strong, unique passwords, turn on two step verification and watch for scams such as fake payment confirmations, requests to send money back and pressure to act fast. If something feels wrong, stop and tell an adult.\n\nSocial media can help a business, but it can also expose a person to harm. Keep business and personal accounts apart, post only what you would be comfortable with for years, and never share your location or schedule with strangers. Online reviews should be honest. Never write fake reviews or pay for them.\n\nYour task: (1) List five ways technology can help your idea. (2) Name five online safety rules for a student business. (3) Explain why fake reviews are wrong.\n\nFlorida standards: Florida Entrepreneurship course standards (course 8812100).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida Entrepreneurship course standards (course 8812100)", "script": "Welcome back. Listen, Proverbs 14:15 says, The simple believeth every word: but the prudent man looketh well to his going. Be prudent online.\n\nNow watch this. Technology lets small businesses reach more people. A website, an online store, a payment app and a spreadsheet can help. Describe products honestly, deliver on time and respect refund policies. Protect customer information, and remember that federal law has special rules for children under thirteen.\n\nDo not copy photos, text, music or software without permission. Copyright protects creators.\n\nPayment accounts for a student business must be set up with a parent or guardian. Never share passwords or account numbers. Use strong passwords, two step verification and watch for scams. If something feels wrong, stop and tell an adult.\n\nKeep business and personal accounts apart. Never share your location with strangers. Never write fake reviews.\n\nYour task is to list uses of technology, name five safety rules and explain fake reviews. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Technology, Online Business and Safety$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Selling, Customer Service and Operations$j$, $j${"prompt": "Write a report of at least 250 words. Use complete sentences and label each part. Colossians 4:6 says, Let your speech be alway with grace, seasoned with salt, that ye may know how ye ought to answer every man.\n\nPart 1: Explain the five steps of honest selling and define feature, benefit and objection. Write a sales pitch for a business idea.\nPart 2: Describe how to handle an unhappy customer using at least five steps. Explain a fair refund policy and a warranty.\nPart 3: Define supplier, inventory and quality. Describe a weekly operations checklist and two safety rules for your business.\nPart 4: Name five online safety rules for a student business and explain why copyright, payment accounts and reviews require care.\nPart 5: Explain how Matthew 20:26 and Proverbs 15:1 shape customer service.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 20 points. Part 4: 20 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Selling, Customer Service and Operations$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Whosoever Will Be Great Shall Be a Servant$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a time you received excellent or poor service and how it made you feel, (2) explains what a servant minded business owner would do differently, (3) explains one online safety rule that every young entrepreneur should follow, and (4) connects your answer to Matthew 20:26, Proverbs 15:1 or Proverbs 14:15. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Is the customer always right? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Whosoever Will Be Great Shall Be a Servant$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: Honest Selling and Communication$j$, $j${"questions": [{"q": "A benefit is:", "options": ["What a feature does for the customer", "A tax", "A fact about the product", "A loan"]}, {"q": "An objection is:", "options": ["A discount", "A sale", "A profit", "A customer's concern"]}, {"q": "Honest selling means:", "options": ["Targeting the confused", "Lying about quality", "Pressuring unsure people", "Never hiding flaws"]}, {"q": "A student sending business messages should:", "options": ["Meet strangers alone", "Share a home address", "Hide messages from adults", "Use an account a parent or guardian can see"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Honest Selling and Communication$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,3,3}'::int[], array[$j$Benefits connect the product to the need.$j$,$j$Objections should be answered honestly.$j$,$j$Truthfulness builds trust.$j$,$j$Safety includes adult oversight.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Honest Selling and Communication$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: Customer Service That Honors God$j$, $j${"questions": [{"q": "Proverbs 15:1 says a soft answer:", "options": ["Starts an argument", "Raises prices", "Costs money", "Turneth away wrath"]}, {"q": "A warranty is a promise to:", "options": ["Repair or replace a faulty product", "Lower the price forever", "Hire a worker", "Skip taxes"]}, {"q": "The first step in handling a complaint is to:", "options": ["Listen without interrupting", "Argue", "Hang up", "Blame the customer"]}, {"q": "Customer privacy means:", "options": ["Keeping personal details safe", "Selling phone numbers", "Posting names online", "Sharing payment details"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Customer Service That Honors God$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,0,0}'::int[], array[$j$Gentle words calm anger.$j$,$j$Warranties protect buyers.$j$,$j$Listening shows respect.$j$,$j$Protect customer information.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Customer Service That Honors God$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Operations, Suppliers and Quality$j$, $j${"questions": [{"q": "A supplier is:", "options": ["A tax office", "A customer", "A source of the materials you need", "A competitor"]}, {"q": "Too much inventory can:", "options": ["Raise profit automatically", "Cut taxes", "Remove risk", "Tie up cash"]}, {"q": "Quality means:", "options": ["Working fast only", "Doing what you promised every time", "Avoiding checks", "Charging the highest price"]}, {"q": "Before selling food, a student should:", "options": ["Sell to strangers alone", "Check health rules and get adult supervision", "Ignore safety", "Skip all rules"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Operations, Suppliers and Quality$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,1}'::int[], array[$j$Suppliers provide materials.$j$,$j$Excess stock locks up money.$j$,$j$Consistency builds a good name.$j$,$j$Food safety rules protect people.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Operations, Suppliers and Quality$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Technology, Online Business and Safety$j$, $j${"questions": [{"q": "Copyright protects:", "options": ["Only taxes", "Only banks", "Creators of original works", "Only buyers"]}, {"q": "A student business payment account should be set up:", "options": ["Without records", "With a parent or guardian", "With a stranger", "Alone in secret"]}, {"q": "A good online safety habit is:", "options": ["Strong unique passwords and two step verification", "Posting your schedule", "Clicking every link", "Sharing passwords"]}, {"q": "Fake online reviews are:", "options": ["Required", "Dishonest", "Smart marketing", "Free advice"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Technology, Online Business and Safety$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,0,1}'::int[], array[$j$Do not copy without permission.$j$,$j$Minors generally need an adult.$j$,$j$Account security protects you.$j$,$j$Reviews must be honest.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Technology, Online Business and Safety$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Selling, Customer Service and Operations$j$, $j${"questions": [{"q": "The first step of honest selling is to:", "options": ["Ask for payment", "Greet the customer with respect", "Argue", "Hide flaws"]}, {"q": "A feature is:", "options": ["A refund", "A fact about the product", "A tax", "A loan"]}, {"q": "To handle a complaint, you should:", "options": ["Ignore it", "Argue", "Listen and offer a fair solution", "Blame the customer"]}, {"q": "A written refund policy should be:", "options": ["Changing daily", "Fair and clear", "Confusing", "Secret"]}, {"q": "Having two suppliers for key items:", "options": ["Reduces the risk of a stoppage", "Is illegal", "Lowers quality", "Raises taxes"]}, {"q": "Ephesians 5:16 speaks of:", "options": ["A good name", "Counting the cost", "Redeeming the time", "Honest weights"]}, {"q": "Which is a scam warning sign?", "options": ["A known supplier", "A clear receipt", "A written contract", "Pressure to act fast and send money back"]}, {"q": "Students should share passwords:", "options": ["With customers", "With no one but a trusted parent or guardian", "In posts", "With suppliers"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Selling, Customer Service and Operations$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,2,1,0,2,3,1}'::int[], array[$j$Respectful greetings open the sale.$j$,$j$Benefits tell what the feature does for the customer.$j$,$j$Calm service wins trust.$j$,$j$Clarity prevents disputes.$j$,$j$Backup suppliers protect operations.$j$,$j$Use time wisely.$j$,$j$Pressure and odd payment requests are red flags.$j$,$j$Protect account security.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Selling, Customer Service and Operations$j$ on conflict (item_id) do nothing;
